t0 = None
stall_t = None

def control(obs):
    global phase, t0, stall_t
    h = obs['hitch_deg']
    v = obs['motion']['v_mps']
    t = obs['t']
    hold = obs['motion'].get('hold_s', 0.0)
    if phase == 'init':
        phase = 'fwd'
        t0 = t
    if phase == 'fwd':
        if t - t0 > 5.0 or h < -10.0:
            phase = 'stop'
        else:
            return {'steer_deg': -30.0, 'speed_mps': 0.3, 'look_deg': -23}
    if phase == 'stop':
        if abs(v) >= 0.05:
            return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': -23}
        phase = 'rev'
        stall_t = None
    steer = max(-30.0, min(30.0, 3.0 * (h + 5.0)))
    if abs(v) < 0.05 and hold <= 0:
        if stall_t is None:
            stall_t = t
        elif t - stall_t > 1.5:
            phase = 'fwd'
            t0 = t
            stall_t = None
            return {'steer_deg': -30.0, 'speed_mps': 0.3, 'look_deg': -23}
    else:
        stall_t = None
    return {'steer_deg': steer, 'speed_mps': -0.5, 'look_deg': -23}

